/**
 * Builds `@nodegx/canvas-look` into what its `exports` map advertises (P112 OWN-011, R2):
 *   dist/index.mjs, dist/index.cjs   the look as data (src/index.ts), platform-neutral, no dependencies
 *   dist/types/*.d.ts                declarations, from tsc (tsconfig.build.json)
 * `dist/` is gitignored: `src/look.ts` is generated by `scripts/canvas-look/generate.js` and is the source of truth.
 */
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import esbuild from 'esbuild';

const here = dirname(fileURLToPath(import.meta.url));
const shared = { bundle: true, platform: 'neutral', target: 'es2019', entryPoints: ['src/index.ts'], logLevel: 'info', absWorkingDir: here };

await esbuild.build({ ...shared, format: 'esm', outfile: 'dist/index.mjs' });
await esbuild.build({ ...shared, format: 'cjs', outfile: 'dist/index.cjs' });

execFileSync(join(here, '..', '..', 'node_modules', '.bin', 'tsc'), ['--project', join(here, 'tsconfig.build.json')], { stdio: 'inherit' });
